import {
  Component, DOCUMENT, ElementRef, inject, input, OnInit,
} from '@angular/core';

@Component({
  selector: 'app-price',
  template: `<div class="price">{{ amount() }}</div>`,
})
export class Price implements OnInit {
  readonly amount = input.required<string>();
  readonly onSale = input(false);
  private readonly host = inject(ElementRef<HTMLElement>).nativeElement;
  private readonly doc = inject(DOCUMENT);

  ngOnInit() {
    if (!this.onSale()) return;
    // Angular has no record of this node, so the DOM no longer
    // matches what the server annotated: hydration fails (NG0500)
    const badge = this.doc.createElement('span');
    badge.textContent = 'Sale';
    this.host.insertBefore(badge, this.host.firstChild);
  }
}

import { Component, input } from '@angular/core';

@Component({
  selector: 'app-price',
  template: `
    @if (onSale()) {
      <span class="badge">Sale</span>
    }
    <div class="price">{{ amount() }}</div>
  `,
})
export class Price {
  // Same inputs on the server and in the browser, so the same
  // DOM: hydration claims the <span> instead of rebuilding it
  readonly amount = input.required<string>();
  readonly onSale = input(false);
}
